<script setup lang="ts">
import {computed,ref} from 'vue'
import {service} from '../services'
import {useAuth} from '../stores/auth'
import {useResource,useTask,confirmAction,formatDate} from '../composables/useData'
import type {User} from '../types/domain'
import PageHeader from '../components/PageHeader.vue'
import LoadState from '../components/LoadState.vue'
import Icon from '../components/Icon.vue'
const auth=useAuth(),users=useResource('users'),departments=useResource('departments'),roles=useResource('roles'),task=useTask(),query=ref(''),dept=ref(''),status=ref(''),dialog=ref(false),resetDialog=ref(false),resetId=ref(''),resetValue=ref('')
const draft=ref<Partial<User>&{password?:string}>({}),filtered=computed(()=>users.items.value.filter(u=>(!query.value||`${u.displayName} ${u.username}`.includes(query.value))&&(!dept.value||u.departmentId===dept.value)&&(!status.value||u.status===status.value)))
function edit(user?:User){draft.value=user?structuredClone(user):{username:'',displayName:'',departmentId:'',roleIds:[],status:'active',password:''};dialog.value=true}
async function save(){await task.run(async()=>{await service.save('users',draft.value);dialog.value=false;await users.load();await auth.refresh()})}
async function toggle(user:User){if(!await confirmAction(`${user.status==='active'?'停用':'启用'}用户「${user.displayName}」？`))return;await task.run(async()=>{await service.save('users',{id:user.id,status:user.status==='active'?'disabled':'active'});await users.load();await auth.refresh()},'账号状态已更新')}
function reset(user:User){resetId.value=user.id;resetValue.value='';resetDialog.value=true}
async function savePassword(){await task.run(async()=>{await service.resetPassword(resetId.value,resetValue.value);resetDialog.value=false},'密码已重置')}
</script>
<template><PageHeader title="用户管理" description="维护团队成员、部门归属和角色关联。"><button class="btn primary" @click="edit()"><Icon name="plus" />新增用户</button></PageHeader><form class="filters" @submit.prevent><label class="search"><Icon name="search"/><input v-model="query" aria-label="搜索用户" placeholder="搜索姓名或用户名"></label><select v-model="dept" aria-label="筛选部门"><option value="">全部部门</option><option v-for="d in departments.items.value" :key="d.id" :value="d.id">{{d.name}}</option></select><select v-model="status" aria-label="筛选账号状态"><option value="">全部状态</option><option value="active">启用</option><option value="disabled">停用</option></select></form><LoadState :loading="users.loading.value" :error="users.error.value||departments.error.value||roles.error.value" :empty="!filtered.length" @retry="users.load();departments.load();roles.load()"><div class="table-wrap"><table class="data-table"><thead><tr><th>姓名 / 用户名</th><th>部门</th><th>角色</th><th>状态</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="user in filtered" :key="user.id"><td><strong class="identity">{{user.displayName}}</strong><span class="sub">{{user.username}}</span></td><td>{{departments.items.value.find(d=>d.id===user.departmentId)?.name||'—'}}</td><td>{{roles.items.value.filter(r=>user.roleIds.includes(r.id)).map(r=>r.name).join('、')}}</td><td><span class="status" :class="user.status==='active'?'success':'error'">{{user.status==='active'?'启用':'停用'}}</span></td><td class="num">{{formatDate(user.createdAt)}}</td><td><div class="row-actions"><button class="text-button" @click="edit(user)">编辑</button><button class="text-button" @click="reset(user)">重置密码</button><button class="text-button" :disabled="task.busy.value" @click="toggle(user)">{{user.status==='active'?'停用':'启用'}}</button></div></td></tr></tbody></table></div><p class="small faint" style="margin-top:16px">共 {{filtered.length}} 位成员</p></LoadState><el-dialog v-model="dialog" :title="draft.id?'编辑用户':'新增用户'" width="560px" :close-on-click-modal="false"><form id="user-form" @submit.prevent="save"><div class="form-grid"><label class="field">姓名<input v-model="draft.displayName" maxlength="40" required></label><label class="field">用户名<input v-model="draft.username" pattern="[A-Za-z0-9_.-]{3,40}" title="3–40 位字母、数字、下划线、点或横线" required :readonly="!!draft.id"></label><label class="field">所属部门<el-select v-model="draft.departmentId" aria-label="所属部门"><el-option v-for="d in departments.items.value" :key="d.id" :label="d.name" :value="d.id" /></el-select></label><label class="field">账号状态<select v-model="draft.status"><option value="active">启用</option><option value="disabled">停用</option></select></label><label class="field span-2">拥有角色<el-select v-model="draft.roleIds" multiple aria-label="拥有角色"><el-option v-for="r in roles.items.value" :key="r.id" :label="r.name" :value="r.id" /></el-select></label><label v-if="!draft.id" class="field span-2">初始密码<input v-model="draft.password" type="password" minlength="8" autocomplete="new-password" required></label></div><p v-if="task.error.value" class="field-error">{{task.error.value}}</p></form><template #footer><button class="btn quiet" @click="dialog=false">取消</button><button class="btn primary" form="user-form" :disabled="task.busy.value">保存用户</button></template></el-dialog><el-dialog v-model="resetDialog" title="重置密码" width="440px"><form id="password-form" @submit.prevent="savePassword"><label class="field">新密码<input v-model="resetValue" type="password" minlength="8" required autocomplete="new-password"></label><p class="small faint" style="margin-top:12px">至少 8 位。请通过团队认可的方式告知成员。</p></form><template #footer><button class="btn quiet" @click="resetDialog=false">取消</button><button class="btn primary" form="password-form" :disabled="task.busy.value">确认重置</button></template></el-dialog></template>
